class Solution {
    /** 15. 3Sum
     * https://leetcode.com/problems/3sum/
     */
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        vector<vector<int>> res;
        sort(nums.begin(), nums.end());
        // set<set<int>> bag;
        // unordered_set<int> bag;
        set<pair<int, int>> bag;
        const int N = nums.size();
        for (int i = N - 2; i >= 0; --i) {
            unordered_set<int> seen;
            int lsum = 1000000;
            for (int j = i + 1; j < N; ++j) {
                const int sum = - nums[j] - nums[i];
                if (sum == lsum) continue;
                if (seen.contains(sum)) {
                    // vector<int> tri({nums[i], sum, nums[j]});
                    if (!bag.contains({nums[i], sum})) {
                        res.push_back({nums[i], sum, nums[j]});
                        bag.insert({nums[i], sum});
                    }
                    lsum = sum;
                }
                seen.insert(nums[j]);
            }
        }
        return res;
    }
};

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        vector<vector<int>> res;
        sort(nums.begin(), nums.end());
        const int N = nums.size();
        auto addTri = [&](const int& ni) {
            const int target = -nums[ni];
            int l = 0, r = ni - 1;
            while (l < r) {
                const int sum = nums[l] + nums[r];
                if (target == sum) {
                    res.push_back({-target, nums[l++], nums[r--]});
                    while (l < r && nums[l] == nums[l - 1]) ++l;
                    while (l < r && nums[r] == nums[r + 1]) --r;
                } else if (target > sum) ++l;
                else --r;
            }
        };
        addTri(N - 1);
        for (int i = N - 2; i >= 2; --i) {
            if (0 > nums[i]) break;
            if (nums[i] == nums[i + 1]) continue;
            addTri(i);
        }
        return res;
    }
};

